WITH ranked AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY page ORDER BY event_time DESC NULLS LAST, id) AS latest_rank FROM web_events QUALIFY latest_rank = 1) SELECT DATE_TRUNC('WEEK', event_time) AS week_start, COUNT(*) FILTER (WHERE event_type = 'page_view') AS page_view_rows, COUNT(*) FILTER (WHERE page = '/checkout') AS checkout_rows, SUM(duration_sec) AS total_duration_sec FROM ranked GROUP BY DATE_TRUNC('WEEK', event_time);
